var e=Math.PI*2;function t(t,n,r,i,a,o){let s=t-r,c=n-i,l=Math.sqrt(s*s+c*c);return .5+.5*Math.sin(e*(l/a+o))}function n(e,t,n,r,i,a){let o=e-n,s=t-r;return .5+.5*Math.sin(i*Math.atan2(s,o)+a)}function r(e,t,n){switch(n){case`sum`:return(e+t)/2;case`product`:return e*t;case`min`:return Math.min(e,t);case`max`:return Math.max(e,t);default:return(e+t)/2}}function i(e,t,n){let r=Math.max(0,Math.min(1,(n-e)/(t-e)));return r*r*(3-2*r)}function a(e,i,a,o,s,c,l,u,d,f){let p=[],m=t(e,i,0,0,a,s-.25)*l;if(o>0&&(m*=n(e,i,0,0,o,-Math.PI/2)),p.push(m),d>=2&&c>0){let r=t(e,i,c,0,a,s-.25)*u;o>0&&(r*=n(e,i,c,0,o,-Math.PI/2)),p.push(r)}for(let n=2;n<d;n++){let r=(n-1)*Math.PI/d,o=Math.cos(r),c=Math.sin(r),l=e*o+i*c,u=-e*c+i*o;p.push(t(l,u,0,0,a,s-.25+n*.1))}let h=p[0];for(let e=1;e<p.length;e++)h=r(h,p[e],f.toLowerCase());return h}function o(e,t,n,r,a){if(n===`none`)return 1;let o;switch(n){case`circle`:o=Math.sqrt(e*e+t*t);break;case`triangle`:o=Math.max(Math.abs(e)*.866+t*.5,-t);break;case`square`:o=Math.max(Math.abs(e),Math.abs(t));break;default:return 1}let s=r;return a>0?i(s+a,s-a,o):o<s?1:0}function s(e){return{r:parseInt(e.slice(1,3),16),g:parseInt(e.slice(3,5),16),b:parseInt(e.slice(5,7),16)}}function c(e,t,n,r){let i=t.width,c=t.height,l=e.createImageData(i,c),u=l.data,d=s(n.fgColor||`#ffffff`),f=s(n.bgColor||`#000000`),p=n.invert===`on`,m=n.phaseSpeed||.1,h=r/60*m,g=n.wavelength||.02,_=n.angularFreq||0,v=(n.phaseOffset||0)+h,y=n.gratingCount||2,b=n.combineMode||`sum`,x=n.threshold||.5,S=n.centreOsc||0,C=(n.centreOffset||0)+Math.sin(h*2)*S,w=n.weightA||1,T=n.weightB||1,E=(n.maskType||`none`).toLowerCase(),D=n.maskSize||1,O=n.maskSoftness||0;for(let e=0;e<c;e++)for(let t=0;t<i;t++){let n=t/i*2-1,r=e/c*2-1,s=a(n,r,g,_,v,C,w,T,y,b),l=o(n,r,E,D,O);s*=l;let m=s>x;p&&(m=!m);let h=m?d:f,S=(e*i+t)*4;u[S]=h.r,u[S+1]=h.g,u[S+2]=h.b,u[S+3]=255}e.putImageData(l,0,0)}var l={id:`moire`,title:`Moiré Generator`,category:`wave`,description:`Generates moiré patterns using radial, angular, and multi-centre gratings. Supports multiple combination modes and mask shapes.`,version:`2.0.0`,infoSections:[{heading:`DESCRIPTION`,body:`Moiré generates binary interference patterns on a 420×420 canvas by composing multiple radial gratings and optionally combining them with angular gratings. Each grating produces a sinusoidal field in normalised [-1, 1] canvas coordinates. Fields from multiple grating centres are combined using one of four modes (sum, product, min, max) and threshold-clipped to binary output using configurable foreground and background colours. The radial grating function is: 0.5 + 0.5 · sin(2π · (r/λ + φ)) where r is the distance from centre (cx, cy). When angularFreq > 0, the radial grating is multiplied by an angular grating: 0.5 + 0.5 · sin(ω · atan2(y−cy, x−cx) + δ), superimposing a sectoral (spoke-like) modulation on the concentric rings. Up to 4 grating centres are supported. Centre A is always at the canvas origin. Centre B activates when gratingCount ≥ 2 and centreOffset > 0. Additional centres (indices 2–3) are placed by rotating the coordinate system. Animation is driven by frame: animationTime = (frame/60) · phaseSpeed. An optional mask (circle, square, triangle) restricts the pattern to a geometric region. Output is always binary two-colour — threshold controls the field value above which a pixel is assigned fgColor. The invert toggle swaps the fg/bg assignment.`},{heading:`ALGORITHM`,body:`Coordinate system: pixels normalised to [-1, 1] via x = (px/W)×2−1, y = (py/H)×2−1. Canvas is 420×420; pixel spacing is 2/420 ≈ 0.00476 per pixel. Radial grating: radialGrating(x,y,cx,cy,λ,φ) = 0.5+0.5·sin(2π·(r/λ+φ)), r=√((x−cx)²+(y−cy)²). Angular grating: angularGrating(x,y,cx,cy,ω,δ) = 0.5+0.5·sin(ω·atan2(y−cy,x−cx)+δ); δ is hardcoded to −π/2. Multi-centre field: centre A at (0,0) weighted by weightA; centre B at (centreOffset_eff, 0) weighted by weightB when gratingCount≥2 and centreOffset>0; centres 2–3 apply coordinate rotation at angle (i−1)·π/count before evaluating radialGrating at origin (unweighted). Centre B oscillation: centreOffset_eff = centreOffset + sin(animationTime×2)×centreOsc. Sequential pairwise combination: intensity_0 = gA; intensity_i = combineMoire(intensity_{i−1}, g_i, mode). Modes: sum=(a+b)/2, product=a×b, min=min(a,b), max=max(a,b). Mask distances: circle=√(x²+y²), square=max(|x|,|y|), triangle=max(|x|·0.866+y·0.5,−y). Soft mask: smoothstep(edge+softness, edge−softness, d) with smoothstep(e0,e1,x)=t²(3−2t), t=clamp((x−e0)/(e1−e0),0,1). Hard mask: d<maskSize?1:0. Output: on = intensity×mask > threshold; if invert then on=!on; color = on ? fg : bg. Functions: radialGrating, angularGrating, combineMoire, smoothstep, computeGratings, computeMask, parseColor, draw.`},{heading:`PARAMETERS`,body:`Gratings — gratingCount: slider 1–4, step 1, default 2; number of active grating centres. wavelength: slider 0.005–0.1, step 0.001, default 0.02; spatial wavelength of rings in normalised units. angularFreq: slider 0–24, step 1, default 0; spoke modulation frequency; 0 disables angular grating. phaseOffset: slider 0–1, step 0.01, default 0; static phase shift applied to all gratings. Combination — combineMode: radio sum|product|min|max, default sum; how grating fields are merged sequentially. threshold: slider 0–1, step 0.01, default 0.5; field value above which a pixel is assigned fgColor. Multi-Centre — centreOffset: slider 0–1, step 0.01, default 0; horizontal displacement of centre B in normalised coords. weightA: slider 0–1, step 0.01, default 1; amplitude weight for centre A. weightB: slider 0–1, step 0.01, default 1; amplitude weight for centre B. Motion — phaseSpeed: slider 0–1, step 0.01, default 0.1; phase advance rate per second at 60 FPS base. centreOsc: slider 0–1, step 0.01, default 0; amplitude of centre B position oscillation during animation. Mask — maskType: radio none|circle|triangle|square, default none; geometric region restricting the pattern. maskSize: slider 0–1, step 0.01, default 1; radius or half-extent of the mask in normalised coords. maskSoftness: slider 0–0.2, step 0.01, default 0; gradient width of the mask edge. Colors — fgColor: color, default #ffffff; foreground pixel colour assigned above threshold. bgColor: color, default #000000; background pixel colour assigned below threshold. invert: radio off|on, default off; swaps fg/bg assignment.`},{heading:`PRESETS`,body:`Classic — gratingCount 2, centreOffset 0.3, combineMode sum, threshold 0.5, no mask. Standard two-centre radial moiré producing concentric interference rings. Angular — gratingCount 2, angularFreq 12, combineMode product, threshold 0.4, maskType circle, maskSize 0.9. Spoke-modulated pattern clipped to a circular region; produces fan-like sectors. Hypnotic — gratingCount 3, centreOsc 0.2, combineMode min, threshold 0.3, phaseSpeed 0.2. Three-centre minimum-combined field with oscillating centre B; produces shifting morphing lobes.`},{heading:`PERFORMANCE`,body:`Complexity: O(W×H×gratingCount). At 420×420 with gratingCount 2: ~350,000 trig calls per frame. At gratingCount 4 with angularFreq>0: ~1.6M trig calls per frame (4 sqrt + 4 atan2 + 8 sin per pixel). Frame budget at 30 FPS: 33ms. No critical performance risk at default settings on modern hardware. During slider interaction, interactionScale 0.5 renders at 210×210 (25% pixel count) for real-time feedback. ImageData allocation: ~705KB per frame; single allocation with no intermediate intensity buffer.`},{heading:`ANIMATION`,body:`Type: infinite — runs continuously with no terminal frame. Frame-driven: animationTime = (frame/60)×phaseSpeed. Phase advances phaseSpeed units per second at 60 FPS base. Animation advances all grating phases simultaneously and drives centre B oscillation via centreOsc. Default 30 FPS. Fully deterministic — same frame and same parameters always produce identical output. Export-compatible for PNG, GIF, and WebM.`},{heading:`KNOWN LIMITATIONS`,body:`Triangle mask uses an approximate equilateral triangle field (max(|x|·0.866+y·0.5,−y)) rather than a true signed-distance function; boundary softness may differ from circle and square masks at equivalent maskSize values. Angular modulation amplitude is fixed at 1; there is no slider to reduce the strength of spoke modulation relative to the radial rings. Mask rotation is not implemented; all mask shapes are axis-aligned. The polygon mask (configurable-side regular polygon) from the original specification is replaced by a fixed square (Chebyshev distance). WebGL fragment shader rendering path is not implemented; only CPU ImageData is available, limiting performance at resolutions above 420×420.`},{heading:`REFERENCES`,body:`Algorithm: standard moiré / interference pattern technique using superposition of circular sinusoidal gratings. No named published algorithm beyond textbook wave interference.`}],compute:{cost:`per-pixel`,interactionScale:.5,idleDelay:200},canvas:{width:420,height:420,context:`2d`,background:`#000000`},animation:{type:`infinite`,defaultFps:30,canPrerender:!0,animatableParams:[`phaseOffset`,`threshold`,`centreOffset`,`wavelength`],sequencer:!0},export:{png:!0,gif:!0,webm:!0,sequence:!0},presets:[{name:`Classic`,values:{gratingCount:2,wavelength:.02,angularFreq:0,phaseOffset:0,combineMode:`sum`,threshold:.5,centreOffset:.3,weightA:1,weightB:1,phaseSpeed:.1,maskType:`none`,fgColor:`#ffffff`,bgColor:`#000000`,invert:`off`}},{name:`Angular`,values:{gratingCount:2,wavelength:.03,angularFreq:12,phaseOffset:0,combineMode:`product`,threshold:.4,centreOffset:.2,weightA:1,weightB:1,phaseSpeed:.05,maskType:`circle`,maskSize:.9,fgColor:`#ffffff`,bgColor:`#000000`,invert:`off`}},{name:`Hypnotic`,values:{gratingCount:3,wavelength:.015,angularFreq:0,phaseOffset:0,combineMode:`min`,threshold:.3,centreOffset:.4,centreOsc:.2,weightA:1,weightB:.8,phaseSpeed:.2,maskType:`none`,fgColor:`#ffffff`,bgColor:`#000000`,invert:`off`}}],parameters:[{group:`Gratings`,params:[{key:`gratingCount`,type:`slider`,label:`Count`,min:1,max:4,step:1,default:2},{key:`wavelength`,type:`slider`,label:`Wavelength`,min:.005,max:.1,step:.001,default:.02,precision:3},{key:`angularFreq`,type:`slider`,label:`Angular Freq`,min:0,max:24,step:1,default:0},{key:`phaseOffset`,type:`slider`,label:`Phase`,min:0,max:1,step:.01,default:0,precision:2}]},{group:`Combination`,params:[{key:`combineMode`,type:`radio`,label:`Mode`,options:[`sum`,`product`,`min`,`max`],default:`sum`},{key:`threshold`,type:`slider`,label:`Threshold`,min:0,max:1,step:.01,default:.5,precision:2}]},{group:`Multi-Centre`,params:[{key:`centreOffset`,type:`slider`,label:`Offset`,min:0,max:1,step:.01,default:0,precision:2},{key:`weightA`,type:`slider`,label:`Weight A`,min:0,max:1,step:.01,default:1,precision:2},{key:`weightB`,type:`slider`,label:`Weight B`,min:0,max:1,step:.01,default:1,precision:2}]},{group:`Motion`,params:[{key:`phaseSpeed`,type:`slider`,label:`Phase Speed`,min:0,max:1,step:.01,default:.1,precision:2},{key:`centreOsc`,type:`slider`,label:`Centre Osc`,min:0,max:1,step:.01,default:0,precision:2}]},{group:`Mask`,params:[{key:`maskType`,type:`radio`,label:`Type`,options:[`none`,`circle`,`triangle`,`square`],default:`none`},{key:`maskSize`,type:`slider`,label:`Size`,min:0,max:1,step:.01,default:1,precision:2},{key:`maskSoftness`,type:`slider`,label:`Softness`,min:0,max:.2,step:.01,default:0,precision:2}]},{group:`Colors`,params:[{key:`fgColor`,type:`color`,label:`Foreground`,default:`#ffffff`},{key:`bgColor`,type:`color`,label:`Background`,default:`#000000`},{key:`invert`,type:`radio`,label:`Invert`,options:[`off`,`on`],default:`off`}]}],draw:c};export{l as SCRIPT_CONFIG};